        public static IReadOnlyCollection<string> RegisteredTables => rules.Keys.ToArray();

        public static IReadOnlyList<int> RequiredPermissionsFor(string table)
        {
            return rules.TryGetValue(table, out var rule) ? rule.RequiredPermissions : [];
        }

        public static IReadOnlyDictionary<string, string> BuildAllowedTables(
            string userName, Func<int[], bool> hasPermission, int? conversationId = null)
        {
            if (string.IsNullOrWhiteSpace(userName))
            {
                throw new InvalidOperationException(
                    "No authenticated user to resolve tenant/role access against -- refusing to build " +
                    "any table access.");
            }

            var escapedUser = PostgresSqlValidator.EscapeStringLiteral(userName);

            var allowed = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

            foreach (var (table, rule) in rules)
            {
                if (!hasPermission(rule.RequiredPermissions))
                {
                    continue;
                }

                if (rule.Template is not null && rule.Template.Contains(ConversationToken, StringComparison.Ordinal))
                {
                    if (!conversationId.HasValue)
                    {
                        continue;
                    }

                    allowed[table] = rule.Template
                        .Replace("{{ESCAPED_USER}}", escapedUser)
                        .Replace(ConversationToken,
                            conversationId.Value.ToString(CultureInfo.InvariantCulture));

                    continue;
                }

                if (rule.Template is null)
                {
                    continue;
                }

                allowed[table] = rule.Template.Replace("{{ESCAPED_USER}}", escapedUser);
            }

            return allowed;
        }
    }
